INSERT INTO objetivos (codigo, nombre, descripcion, indicaciones, orden) VALUES ('fuerza', 'Fuerza', 'Levantar más peso en los ejercicios básicos: sentadilla, banca, peso muerto y press militar.', 'Pocas repeticiones con mucho peso. Descansa 2 a 3 minutos entre series.', 1) ON DUPLICATE KEY UPDATE nombre = VALUES(nombre), descripcion = VALUES(descripcion), indicaciones = VALUES(indicaciones), orden = VALUES(orden);
INSERT INTO objetivos (codigo, nombre, descripcion, indicaciones, orden) VALUES ('hipertrofia', 'Hipertrofia', 'Ganar masa muscular con más volumen de trabajo por grupo muscular.', '8 a 15 repeticiones cerca del fallo. Descansa 2 minutos en los básicos y 60 a 90 segundos en el resto.', 2) ON DUPLICATE KEY UPDATE nombre = VALUES(nombre), descripcion = VALUES(descripcion), indicaciones = VALUES(indicaciones), orden = VALUES(orden);
INSERT INTO objetivos (codigo, nombre, descripcion, indicaciones, orden) VALUES ('hibrido', 'Híbrido', 'Fuerza en los básicos más un circuito final para mejorar la resistencia.', 'Básicos pesados y cierra con el circuito a buen ritmo. Descansa 90 segundos.', 3) ON DUPLICATE KEY UPDATE nombre = VALUES(nombre), descripcion = VALUES(descripcion), indicaciones = VALUES(indicaciones), orden = VALUES(orden);
INSERT INTO objetivos (codigo, nombre, descripcion, indicaciones, orden) VALUES ('salud', 'Salud', 'Moverte mejor y mantenerte activo con rutinas de cuerpo completo.', 'Cargas moderadas y buena técnica. Descansa 60 segundos entre series.', 4) ON DUPLICATE KEY UPDATE nombre = VALUES(nombre), descripcion = VALUES(descripcion), indicaciones = VALUES(indicaciones), orden = VALUES(orden);
INSERT INTO plantillas_rutina (objetivo_id, codigo, nombre) SELECT id, 'cuerpo_a', 'Cuerpo completo A' FROM objetivos WHERE codigo = 'fuerza' ON DUPLICATE KEY UPDATE nombre = VALUES(nombre);
INSERT INTO plantilla_ejercicios (plantilla_id, ejercicio_id, series, repeticiones, orden) SELECT (SELECT p.id FROM plantillas_rutina p JOIN objetivos o ON o.id = p.objetivo_id WHERE o.codigo = 'fuerza' AND p.codigo = 'cuerpo_a'), (SELECT id FROM ejercicios WHERE nombre = 'Sentadilla' AND usuario_id IS NULL ORDER BY id LIMIT 1), 5, 5, 1;
