-- ---------------------------------------------------------------------
-- Divisiones: qué sesión toca el 1er, 2do... día de entrenamiento
-- ---------------------------------------------------------------------
DELETE FROM divisiones_objetivo;

SET SQL_SAFE_UPDATES = 1;

-- Revisión rápida: deberías ver 4 objetivos con sus plantillas y divisiones
SELECT o.nombre AS objetivo,
       (SELECT COUNT(*) FROM plantillas_rutina p WHERE p.objetivo_id = o.id) AS plantillas,
       (SELECT COUNT(*) FROM divisiones_objetivo d WHERE d.objetivo_id = o.id) AS dias_configurados
  FROM objetivos o ORDER BY o.orden;
